import{c as a,Q as r,j as n,m as i,g as e,n as t}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Diffusion Models for Language and Code Generation — 深度研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-07-diffusion-language-models.md","filePath":"research/reports/2026-06-07-diffusion-language-models.md","lastUpdated":1780844007000}'),s={name:"research/reports/2026-06-07-diffusion-language-models.md"};function l(d,o,f,g,u,h){return r(),n("div",null,[...o[0]||(o[0]=[i('<h1 id="diffusion-models-for-language-and-code-generation-—-深度研究報告" tabindex="-1">Diffusion Models for Language and Code Generation — 深度研究報告 <a class="header-anchor" href="#diffusion-models-for-language-and-code-generation-—-深度研究報告" aria-label="Permalink to &quot;Diffusion Models for Language and Code Generation — 深度研究報告&quot;">​</a></h1><p><strong>日期</strong>：2026-06-07 | <strong>研究範圍</strong>：Masked diffusion language models, discrete diffusion, MDLM, LLM+diffusion hybrid, text generation via diffusion</p><hr><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>Diffusion 模型於影像生成領域取得突破後，近兩年研究社群積極將其延伸至離散語言空間。以 MDLM [Sahoo et al., 2024]、SEDD [Lou et al., 2023] 及 LLaDA [Nie et al., 2025] 為代表的研究表明：masked discrete diffusion 架構已能在標準語言建模基準上接近甚至在特定任務超越自回歸（AR）基線。最關鍵洞見有二：其一，diffusion LM 對雙向上下文的天然建模能力使其在複雜推理、規劃與反向生成任務上展現結構性優勢；其二，通過 block diffusion [Arriola et al., 2025] 等混合架構，AR 與 diffusion 兩種範式的互補性正被系統性地整合，開啟了「連續品質-延遲-可控性」三維最佳化的新設計空間。代碼生成方面，Dream-Coder 7B [Xie et al., 2025] 的出現標誌 diffusion LM 已進入實用代碼生成階段。</p><hr><h2 id="_1-背景與動機" tabindex="-1">1. 背景與動機 <a class="header-anchor" href="#_1-背景與動機" aria-label="Permalink to &quot;1. 背景與動機&quot;">​</a></h2><h3 id="_1-1-自回歸模型的結構性限制" tabindex="-1">1.1 自回歸模型的結構性限制 <a class="header-anchor" href="#_1-1-自回歸模型的結構性限制" aria-label="Permalink to &quot;1.1 自回歸模型的結構性限制&quot;">​</a></h3><p>自 GPT 系列奠定地位以來，自回歸（Autoregressive，AR）語言模型主導了自然語言處理領域長達五年。AR 模型以 token-by-token 的左到右生成策略為核心，優勢在於訓練目標清晰（next-token prediction）、推理穩定、與人類書寫習慣高度契合。然而此架構存在數個根本性限制：</p><ol><li><strong>順序生成瓶頸</strong>：每個 token 的生成依賴前序輸出，推理無法原生並行，在長序列生成時延遲高。</li><li><strong>單向上下文偏差</strong>：訓練期間模型只見左側上下文，對需要全局約束滿足的任務（如數獨、邏輯規劃、密碼學謎題）結構性不利。</li><li><strong>逆向詛咒（Reversal Curse）</strong>：AR 模型在「A implies B」方向上訓練後，難以可靠推導「B implies A」，在反向問答、詩歌補完等任務上表現退化。</li><li><strong>可控性有限</strong>：插值（infilling）、條件重寫等需要修改已生成 token 的任務需要特殊架構（如 span masking），無法在標準 AR 框架下自然表達。</li></ol><h3 id="_1-2-diffusion-模型作為替代範式的崛起" tabindex="-1">1.2 Diffusion 模型作為替代範式的崛起 <a class="header-anchor" href="#_1-2-diffusion-模型作為替代範式的崛起" aria-label="Permalink to &quot;1.2 Diffusion 模型作為替代範式的崛起&quot;">​</a></h3><p>Diffusion 模型的核心思想源自非平衡熱力學：通過一個前向過程（forward process）逐步將數據破壞為純雜訊，再學習一個反向過程（reverse process）從雜訊中恢復原始數據。在連續域（圖像、音頻、分子結構）中，此框架以 DDPM [Ho et al., 2020] 和 DALL-E 系列為代表取得了顯著成就。</p><p>將 diffusion 延伸至離散語言空間的核心挑戰在於：標準分數匹配（score matching）依賴連續空間的梯度結構，在離散 token 空間中不直接適用。早期嘗試（如 D3PM [Austin et al., 2021]）雖建立了理論基礎，但生成質量與 AR 模型之間存在巨大差距。2023-2025 年間，多篇關鍵工作系統性地縮小了這一差距，使 discrete diffusion LM 從學術概念走向可與 AR 競爭的實用架構。</p><hr><h2 id="_2-核心概念分析" tabindex="-1">2. 核心概念分析 <a class="header-anchor" href="#_2-核心概念分析" aria-label="Permalink to &quot;2. 核心概念分析&quot;">​</a></h2><h3 id="_2-1-masked-diffusion-的數學框架" tabindex="-1">2.1 Masked Diffusion 的數學框架 <a class="header-anchor" href="#_2-1-masked-diffusion-的數學框架" aria-label="Permalink to &quot;2.1 Masked Diffusion 的數學框架&quot;">​</a></h3><p>Masked Discrete Diffusion 是目前最成功的離散 diffusion LM 子類別。其核心思想是：將「加雜訊」定義為以一定概率將 token 替換為 <code>[MASK]</code> 符號（absorbing state），將「去雜訊」定義為預測並恢復被遮蔽的 token。</p><p><strong>前向過程</strong>：給定輸入序列 $x_0$，在時間步 $t \\in [0,1]$ 時，每個 token 以概率 $\\alpha(t)$ 被替換為 <code>[MASK]</code>，以概率 $1-\\alpha(t)$ 保持原值。當 $t \\to 1$ 時，序列趨近於全部被遮蔽的狀態。</p><p><strong>反向過程</strong>：訓練一個 Transformer（通常為雙向 BERT-style）以預測 $x_0$，即在給定部分遮蔽序列 $x_t$ 的條件下，估計原始 token 的分佈。</p><p><strong>SUBS 參數化</strong> [Sahoo et al., 2024]：MDLM 的關鍵貢獻之一是引入「substitution-based」參數化，將 absorbing-state diffusion 的訓練損失化簡為加權的 MLM（Masked Language Modeling）交叉熵之和：</p>',20),e("p",null,[t("$$\\mathcal{L}"),e("em",{"t,":"",x_t:""},"{\\text{SUBS}} = \\mathbb{E}"),t(" \\left[ w(t) \\cdot \\text{CE}(\\hat{x}_0, x_0) \\right]$$")],-1),i('<p>其中 $w(t)$ 為時間依賴的權重函數。這個化簡的重要性在於：它使 diffusion LM 的訓練與 BERT 的 MLM 訓練直接等價，可直接繼承 BERT 的工程最佳實踐（混合精度訓練、學習率排程、大 batch 訓練等）。</p><h3 id="_2-2-score-entropy-離散-diffusion-sedd" tabindex="-1">2.2 Score Entropy 離散 Diffusion（SEDD） <a class="header-anchor" href="#_2-2-score-entropy-離散-diffusion-sedd" aria-label="Permalink to &quot;2.2 Score Entropy 離散 Diffusion（SEDD）&quot;">​</a></h3><p>SEDD [Lou et al., 2023] 提出了一條不同的理論路線。其核心貢獻是將連續分數匹配（score matching）的概念延伸至離散空間，引入「分數熵」（score entropy）作為離散數據的訓練目標：</p><p>$$\\mathcal{L}<em>{\\text{SEDD}} = \\mathbb{E} \\left[ \\sum</em><code>{y \\neq x_t}</code> q(y | x_t) \\left( \\frac{p(x_t | y)}{p(x_t)} - \\log \\frac{p(x_t | y)}{p(x_t)} - 1 \\right) \\right]$$</p><p>此目標函數在理論上比早期 D3PM 的變分下界（ELBO）更緊，使得採樣效率大幅提升：SEDD 可以用 <strong>32× 更少的網路前向傳播</strong>達到與完整採樣步驟可比的生成品質。</p><h3 id="_2-3-block-diffusion-ar-與-diffusion-的橋接" tabindex="-1">2.3 Block Diffusion：AR 與 Diffusion 的橋接 <a class="header-anchor" href="#_2-3-block-diffusion-ar-與-diffusion-的橋接" aria-label="Permalink to &quot;2.3 Block Diffusion：AR 與 Diffusion 的橋接&quot;">​</a></h3><p>Block Diffusion [Arriola et al., 2025] 引入了一個統一框架，通過「區塊」結構在 AR 與 diffusion 之間平滑插值：</p><ul><li><strong>Block AR</strong>：每個區塊自回歸地依序生成（相當於標準 AR，區塊大小=1）</li><li><strong>Block Diffusion</strong>：區塊內部使用 masked diffusion 並行去雜訊，區塊間依序展開</li><li><strong>Pure Diffusion</strong>：整個序列視為單一區塊（傳統 diffusion LM）</li></ul><p>此設計同時解決了：(1) 傳統 diffusion LM 只能生成固定長度序列的問題；(2) 通過 KV cache 在區塊間實現推理加速；(3) 為訓練引入梯度變異估計器（gradient variance estimators）和數據驅動的雜訊排程。</p><h3 id="_2-4-多粒度-diffusion-建模-mgdm" tabindex="-1">2.4 多粒度 Diffusion 建模（MGDM） <a class="header-anchor" href="#_2-4-多粒度-diffusion-建模-mgdm" aria-label="Permalink to &quot;2.4 多粒度 Diffusion 建模（MGDM）&quot;">​</a></h3><p>MGDM [Ye et al., 2024] 針對複雜推理任務提出了一個關鍵改進：識別到自回歸模型在「子目標不平衡」（subgoal imbalance）問題上的缺陷，即模型在簡單子任務上過度訓練而在關鍵約束步驟上訓練不足。MGDM 通過動態調整不同子目標的採樣難度，使 diffusion 模型在訓練中更多關注困難子目標（如數獨中的約束滿足節點、Countdown 謎題中的組合邊界）。</p><hr><h2 id="_3-關鍵論文與研究成果" tabindex="-1">3. 關鍵論文與研究成果 <a class="header-anchor" href="#_3-關鍵論文與研究成果" aria-label="Permalink to &quot;3. 關鍵論文與研究成果&quot;">​</a></h2><h3 id="_3-1-mdlm-—-simple-and-effective-masked-diffusion-language-models" tabindex="-1">3.1 MDLM — Simple and Effective Masked Diffusion Language Models <a class="header-anchor" href="#_3-1-mdlm-—-simple-and-effective-masked-diffusion-language-models" aria-label="Permalink to &quot;3.1 MDLM — Simple and Effective Masked Diffusion Language Models&quot;">​</a></h3><p><strong>[Sahoo et al., NeurIPS 2024]</strong> | arXiv:2406.07524</p><p><strong>方法</strong>：MDLM 建立於 absorbing-state masked diffusion 之上，核心貢獻是 SUBS 參數化（將 diffusion 損失化簡為 MLM 損失的加權和）+ Rao-Blackwellized 目標（通過條件期望降低梯度方差）+ 現代工程訓練配方（大 batch、混合精度、余弦學習率排程）。</p><p><strong>量化結果</strong>：</p><ul><li>LM1B 測試集：困惑度（perplexity）達到 <strong>75.1</strong>，優於所有先前 diffusion LM（D3PM、MDLM 前身）</li><li>OpenWebText：困惑度 <strong>21.4</strong>，接近同規模 AR 模型（差距縮小至 15–25%）</li><li>支援任意長度半自回歸生成，打破固定長度限制</li></ul><p><strong>意義</strong>：MDLM 確立了 masked diffusion + MLM 損失等價這一核心洞見，大幅降低了 diffusion LM 的工程門檻。</p><h3 id="_3-2-llada-—-large-language-diffusion-models" tabindex="-1">3.2 LLaDA — Large Language Diffusion Models <a class="header-anchor" href="#_3-2-llada-—-large-language-diffusion-models" aria-label="Permalink to &quot;3.2 LLaDA — Large Language Diffusion Models&quot;">​</a></h3><p><strong>[Nie et al., 2025]</strong> | arXiv:2502.09992</p><p><strong>方法</strong>：LLaDA 是首個從頭（from scratch）以完整預訓練 + SFT 範式訓練的 <strong>8B 參數</strong> masked diffusion LM。前向過程為均勻遮蔽，反向過程由 Transformer 參數化以預測 <code>[MASK]</code> 的原始 token，損失函數為似然基準的優化目標（likelihood-based objective）。SFT 階段直接在回應部分施加遮蔽，實現指令跟隨能力。</p><p><strong>量化結果</strong>：</p><ul><li>與 LLaMA3 8B 在上下文學習（in-context learning）任務上競爭性持平</li><li><strong>逆向詩歌補完任務</strong>：超越 GPT-4o（LLaDA 因雙向依賴自然解決 reversal curse）</li><li>數學與代碼生成基準上展現強擴展性（scaling），後續工作延伸至 LLaDA2.0（16B / 100B MoE 變體）</li></ul><p><strong>意義</strong>：LLaDA 是第一個在語言建模的主流評估（instruction following、數學、代碼）上與頂級 AR LLM 量級可比的 diffusion 模型，證明「大型語言模型 = 自回歸」的假設可以被挑戰。</p><h3 id="_3-3-sedd-—-score-entropy-discrete-diffusion" tabindex="-1">3.3 SEDD — Score Entropy Discrete Diffusion <a class="header-anchor" href="#_3-3-sedd-—-score-entropy-discrete-diffusion" aria-label="Permalink to &quot;3.3 SEDD — Score Entropy Discrete Diffusion&quot;">​</a></h3><p><strong>[Lou, Meng, Ermon, ICML 2024 Oral]</strong> | arXiv:2310.16834</p><p><strong>方法</strong>：SEDD 從理論出發，將連續分數匹配延伸至離散空間，提出分數熵（score entropy）作為離散數據的訓練目標。採樣時利用離散 Langevin 動力學（discrete Langevin dynamics）以更少步驟完成高品質生成。</p><p><strong>量化結果</strong>：</p><ul><li>相比先前語言 diffusion 模型（如 D3PM），困惑度降低 <strong>25–75%</strong></li><li>以 <strong>32× 更少網路前向傳播</strong>達到可比生成品質</li><li>在 GPT-2 規模（117M、345M）上超越 GPT-2 的生成品質（perplexity 及人工評分）</li><li>原生支援 infilling（插補）、非左到右解碼，無需重新訓練</li></ul><p><strong>意義</strong>：SEDD 從理論層面解釋了為何早期離散 diffusion 效率低下，並提供了有原理依據的解決方案，成為後續工作的重要基礎。</p><h3 id="_3-4-mgdm-—-beyond-autoregression" tabindex="-1">3.4 MGDM — Beyond Autoregression <a class="header-anchor" href="#_3-4-mgdm-—-beyond-autoregression" aria-label="Permalink to &quot;3.4 MGDM — Beyond Autoregression&quot;">​</a></h3><p><strong>[Ye et al., ICLR 2025]</strong> | arXiv:2410.14157</p><p><strong>方法</strong>：提出「子目標不平衡」問題的形式化定義，以及多粒度 diffusion 建模（MGDM）。MGDM 在 diffusion 訓練的雜訊排程中動態提升困難子目標的採樣概率，使模型在關鍵約束步驟上獲得更多梯度信號。</p><p><strong>量化結果</strong>（不使用搜索技術）：</p><ul><li><strong>Countdown 謎題</strong>：91.5% 準確率 vs AR 基線 45.8%（提升 <strong>+45.7pp</strong>）</li><li><strong>數獨（Sudoku）</strong>：100% 準確率 vs AR 基線 20.7%（提升 <strong>+79.3pp</strong>）</li><li><strong>布林可滿足性問題（Boolean SAT）</strong>：顯著優於 AR 基線</li></ul><p><strong>意義</strong>：MGDM 提供了 diffusion LM 在結構性優勢任務上的最強量化證據，對 AI 規劃和推理領域意義重大。</p><h3 id="_3-5-block-diffusion-bd3-lms" tabindex="-1">3.5 Block Diffusion BD3-LMs <a class="header-anchor" href="#_3-5-block-diffusion-bd3-lms" aria-label="Permalink to &quot;3.5 Block Diffusion BD3-LMs&quot;">​</a></h3><p><strong>[Arriola et al., ICLR 2025 Oral]</strong> | arXiv:2503.09573</p><p><strong>方法</strong>：將序列分解為固定大小的區塊，區塊間自回歸（AR）依序展開，區塊內使用 masked diffusion 並行去雜訊。引入梯度變異估計器（gradient variance estimators）和數據驅動雜訊排程（data-driven noise schedules）以穩定訓練。</p><p><strong>量化結果</strong>：</p><ul><li>在標準語言建模基準上達到 diffusion 模型中的 SOTA 似然（likelihood）</li><li>解決固定長度限制，支援任意長度序列生成</li><li>KV cache + 並行 token 採樣結合，在推理效率上同時繼承 AR 和 diffusion 的優勢</li></ul><h3 id="_3-6-dream-coder-7b-—-代碼生成-diffusion-lm" tabindex="-1">3.6 Dream-Coder 7B — 代碼生成 Diffusion LM <a class="header-anchor" href="#_3-6-dream-coder-7b-—-代碼生成-diffusion-lm" aria-label="Permalink to &quot;3.6 Dream-Coder 7B — 代碼生成 Diffusion LM&quot;">​</a></h3><p><strong>[Xie et al., 2025]</strong> | arXiv:2509.01142</p><p><strong>方法</strong>：從預訓練自回歸 LLM checkpoint 出發，通過持續訓練轉換為離散 diffusion 框架（continuous-time weighted cross-entropy objective）。採用三種自適應解碼策略：sketch-first（複雜算法先生成骨架）、left-to-right（簡單補全）、interleaved reasoning（代碼理解任務）。使用 RLVR（RL with verifiable rewards）在可驗證獎勵上進行強化學習微調。</p><p><strong>量化結果</strong>：</p><ul><li>LiveCodeBench pass@1：<strong>21.4%</strong>，與更大規模 diffusion 模型競爭</li><li>完整開源：checkpoint、訓練配方、預處理管道、推理代碼</li></ul><hr><h2 id="_4-方法論比較" tabindex="-1">4. 方法論比較 <a class="header-anchor" href="#_4-方法論比較" aria-label="Permalink to &quot;4. 方法論比較&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>Masked Diffusion（MDLM/LLaDA）</th><th>Score Entropy（SEDD）</th><th>Block Diffusion（BD3-LM）</th></tr></thead><tbody><tr><td><strong>理論基礎</strong></td><td>Absorbing-state Markov chain</td><td>離散分數匹配</td><td>AR + Diffusion 混合</td></tr><tr><td><strong>採樣效率</strong></td><td>中等（需多步去雜訊）</td><td>高（32× 節省）</td><td>高（KV cache + 並行）</td></tr><tr><td><strong>生成長度</strong></td><td>固定長度（除 Block 變體）</td><td>固定長度</td><td>任意長度</td></tr><tr><td><strong>訓練難度</strong></td><td>低（等價 MLM 損失）</td><td>中等（需離散 Langevin）</td><td>中高（梯度方差控制）</td></tr><tr><td><strong>可控性</strong></td><td>中（掩蔽模式可控）</td><td>高（原生支援 infilling）</td><td>中高（區塊級可控）</td></tr><tr><td><strong>規劃/推理任務</strong></td><td>強（雙向依賴）</td><td>強</td><td>強</td></tr><tr><td><strong>工程成熟度</strong></td><td>高（MLM 繼承）</td><td>中</td><td>中</td></tr></tbody></table><p><strong>選擇建議</strong>：</p><ul><li>快速工程落地、從 BERT 遷移 → <strong>MDLM</strong>（最低訓練門檻）</li><li>需要高採樣效率或非順序生成 → <strong>SEDD</strong></li><li>需要任意長度生成且兼顧推理速度 → <strong>BD3-LM</strong></li><li>複雜規劃/約束任務 → <strong>MGDM</strong>（優先選擇 diffusion 架構）</li><li>代碼生成且有預訓練 AR 基礎 → <strong>Dream-Coder 風格轉換</strong></li></ul><hr><h2 id="_5-前沿趨勢與開放問題" tabindex="-1">5. 前沿趨勢與開放問題 <a class="header-anchor" href="#_5-前沿趨勢與開放問題" aria-label="Permalink to &quot;5. 前沿趨勢與開放問題&quot;">​</a></h2><h3 id="_5-1-2024-2025-主要趨勢" tabindex="-1">5.1 2024-2025 主要趨勢 <a class="header-anchor" href="#_5-1-2024-2025-主要趨勢" aria-label="Permalink to &quot;5.1 2024-2025 主要趨勢&quot;">​</a></h3><p><strong>規模化驗證</strong>：LLaDA 的 8B 版本及後續 LLaDA2.0 的 16B/100B MoE 變體表明，masked diffusion 架構具備可擴展性（scalability），不再是只在小規模上有效的研究玩具。</p><p><strong>AR-Diffusion 融合加速</strong>：Block Diffusion [Arriola et al., 2025] 和 Dream-Coder [Xie et al., 2025]（從 AR checkpoint 轉換）展示了兩種範式並非對立，混合架構與轉換策略正成為重要研究方向。</p><p><strong>特定任務優勢固化</strong>：MGDM [Ye et al., 2024] 量化確認了 diffusion LM 在規劃/推理任務上的結構性優勢，預期後續在 AI agent、代碼驗證、形式化推理領域將有更多 diffusion-first 設計出現。</p><h3 id="_5-2-主要開放問題" tabindex="-1">5.2 主要開放問題 <a class="header-anchor" href="#_5-2-主要開放問題" aria-label="Permalink to &quot;5.2 主要開放問題&quot;">​</a></h3><ol><li><strong>困惑度差距</strong>：即使最佳 masked diffusion LM（如 LLaDA 8B）仍與同等規模 AR LLM 在標準語言建模困惑度上存在 15-25% 差距，根本原因尚未完全理解。</li><li><strong>長序列訓練穩定性</strong>：超過 4096 token 的長文本 diffusion 訓練存在梯度爆炸和 attention 計算瓶頸，需要針對性方案。</li><li><strong>RLHF 相容性</strong>：標準 RLHF 依賴 token-level log-probability 作為獎勵信號，在 diffusion 框架下需要重新設計（Dream-Coder 的 RLVR 是初步嘗試）。</li><li><strong>多模態擴展</strong>：diffusion 在圖像模態天然適用，但文本-圖像聯合 diffusion LM（統一 token 空間）仍處於早期探索。</li></ol><hr><h2 id="_6-實踐意義與應用建議" tabindex="-1">6. 實踐意義與應用建議 <a class="header-anchor" href="#_6-實踐意義與應用建議" aria-label="Permalink to &quot;6. 實踐意義與應用建議&quot;">​</a></h2><h3 id="對-ai-工程師" tabindex="-1">對 AI 工程師 <a class="header-anchor" href="#對-ai-工程師" aria-label="Permalink to &quot;對 AI 工程師&quot;">​</a></h3><p><strong>何時應考慮 Diffusion LM 替代 AR</strong>：</p><ul><li>任務需要<strong>全局約束滿足</strong>（程式碼格式、結構化輸出、JSON schema）→ diffusion 的雙向建模天然適合</li><li>需要高質量<strong>文本插補（infilling）</strong> 而不願訓練特殊 AR 插補模型 → SEDD 原生支援</li><li><strong>批量生成延遲敏感</strong>而非逐 token 流式展示 → diffusion 並行去雜訊可降低 batch latency</li></ul><p><strong>遷移路徑建議</strong>：</p><ol><li>從預訓練 AR checkpoint 出發（Dream-Coder 路徑）而非從頭訓練，可大幅降低計算成本</li><li>損失函數選擇 MDLM 的 SUBS 參數化（等價 MLM，工程最成熟）</li><li>評估框架須包含 infilling 和非順序生成任務，僅用 perplexity 會低估 diffusion 優勢</li></ol><h3 id="對研究者" tabindex="-1">對研究者 <a class="header-anchor" href="#對研究者" aria-label="Permalink to &quot;對研究者&quot;">​</a></h3><ul><li><strong>基準選擇</strong>：確保評估集包含逆向任務（reversal curse）和規劃任務（Sudoku/Countdown），這些是 diffusion 優勢最顯著的維度</li><li><strong>消融設計</strong>：SUBS 參數化 vs 分數熵兩條路線的公平比較在文獻中仍不充分</li><li><strong>與 RLHF 結合</strong>：RLVR（可驗證獎勵 RL）是目前最可行的 alignment 路徑</li></ul><hr><h2 id="_7-研究缺口與未來方向" tabindex="-1">7. 研究缺口與未來方向 <a class="header-anchor" href="#_7-研究缺口與未來方向" aria-label="Permalink to &quot;7. 研究缺口與未來方向&quot;">​</a></h2><ol><li><p><strong>理論層面</strong>：為何 masked diffusion 的困惑度存在系統性差距？是 absorbing state 設計的固有限制，還是訓練目標優化不足？需要更深入的理論分析。</p></li><li><p><strong>代碼生成</strong>：Dream-Coder 7B 的 21.4% pass@1 仍低於同規模 AR 代碼模型（如 DeepSeek-Coder），sketch-first 解碼策略的優化空間大，特別是在多輪互動場景下。</p></li><li><p><strong>長期依賴</strong>：擴展至書籍/文章級長文本（100K+ token）的 masked diffusion 訓練方案仍缺乏。</p></li><li><p><strong>推理時擴展</strong>：diffusion LM 的「採樣步數即計算預算」特性為 inference-time scaling（類似 Chain-of-Thought/Best-of-N）提供了自然接口，但系統性研究尚缺。</p></li><li><p><strong>中文/多語言</strong>：幾乎所有重要 diffusion LM 工作均以英文為主，中文及其他非拉丁語系語言（特別是 CJK token 空間下的 absorbing state 設計）尚未充分探索。</p></li></ol><hr><h2 id="附錄-參考文獻" tabindex="-1">附錄：參考文獻 <a class="header-anchor" href="#附錄-參考文獻" aria-label="Permalink to &quot;附錄：參考文獻&quot;">​</a></h2><ol><li><p><strong>Sahoo, S. S., Arriola, M., Schiff, Y., Gokaslan, A., Marroquin, E., Chiu, J. T., Rush, A., &amp; Kuleshov, V. (2024).</strong> Simple and Effective Masked Diffusion Language Models. <em>NeurIPS 2024</em>. arXiv:2406.07524. <a href="https://arxiv.org/abs/2406.07524" target="_blank" rel="noreferrer">https://arxiv.org/abs/2406.07524</a></p></li><li><p><strong>Nie, S., Zhu, F., You, Z., Zhang, X., Ou, J., Hu, J., Zhou, J., Lin, Y., Wen, J.-R., &amp; Li, C. (2025).</strong> Large Language Diffusion Models. arXiv:2502.09992. <a href="https://arxiv.org/abs/2502.09992" target="_blank" rel="noreferrer">https://arxiv.org/abs/2502.09992</a></p></li><li><p><strong>Lou, A., Meng, C., &amp; Ermon, S. (2023).</strong> Discrete Diffusion Modeling by Estimating the Ratios of the Data Distribution. <em>ICML 2024 Oral</em>. arXiv:2310.16834. <a href="https://arxiv.org/abs/2310.16834" target="_blank" rel="noreferrer">https://arxiv.org/abs/2310.16834</a></p></li><li><p><strong>Ye, J., Gao, J., Gong, S., Zheng, L., Jiang, X., Li, Z., &amp; Kong, L. (2024).</strong> Beyond Autoregression: Discrete Diffusion for Complex Reasoning and Planning. <em>ICLR 2025</em>. arXiv:2410.14157. <a href="https://arxiv.org/abs/2410.14157" target="_blank" rel="noreferrer">https://arxiv.org/abs/2410.14157</a></p></li><li><p><strong>Arriola, M., Gokaslan, A., Chiu, J. T., Yang, Z., Qi, Z., Han, J., Sahoo, S. S., &amp; Kuleshov, V. (2025).</strong> Block Diffusion: Interpolating Between Autoregressive and Diffusion Language Models. <em>ICLR 2025 Oral</em>. arXiv:2503.09573. <a href="https://arxiv.org/abs/2503.09573" target="_blank" rel="noreferrer">https://arxiv.org/abs/2503.09573</a></p></li><li><p><strong>Xie, Z., Ye, J., Zheng, L., Gao, J., Dong, J., Wu, Z., Zhao, X., Gong, S., Jiang, X., Li, Z., &amp; Kong, L. (2025).</strong> Dream-Coder 7B: An Open Diffusion Language Model for Code. arXiv:2509.01142. <a href="https://arxiv.org/abs/2509.01142" target="_blank" rel="noreferrer">https://arxiv.org/abs/2509.01142</a></p></li><li><p><strong>Austin, J., Johnson, D. D., Ho, J., Tarlow, D., &amp; van den Berg, R. (2021).</strong> Structured Denoising Diffusion Models in Discrete State-Spaces. <em>NeurIPS 2021</em>. （D3PM，離散 diffusion 早期基礎工作）</p></li><li><p><strong>Ho, J., Jain, A., &amp; Abbeel, P. (2020).</strong> Denoising Diffusion Probabilistic Models. <em>NeurIPS 2020</em>. （DDPM，連續 diffusion 基礎）</p></li></ol>',75)])])}const D=a(s,[["render",l]]);export{c as __pageData,D as default};
